{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Although the link between these factors and sport performance has been extensively examined in the literature, there remains a critical need for further research into their practical application and the role they play in mapping the psychological profiles of athletes [3-6]. ... However, there are still gaps in the measurement and applicability of these psychological factors [9].",
      "reason": "The Introduction describes the current state of knowledge (extensive literature on psychological factors and performance) and identifies uncertainties/gaps (practical application, measurement, applicability)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "This study aims to conduct a meta-analysis focusing on the associations between psychological constructs and sport performance, as these relationships have been widely examined in existing literature [12,13]. ... This study aims to present a systematic review of the existing literature, providing insights that can guide future research and field practice [8,19].",
      "reason": "The Introduction explicitly states the aims of the review/meta-analysis and explains the need for further rigorous research and practical guidance, establishing the importance of conducting the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Meta-analytic studies have demonstrated that these factors are critically linked to performance enhancement, yet further methodologically rigorous research is required to explore these associations in greater depth [22,23].",
      "reason": "The Introduction acknowledges existing meta-analytic studies and implies the need for the current review, but it does not explicitly identify or cite specific previous systematic reviews as updates or replications would require."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of associations between psychological factors and sports performance, not a review of intervention effects, so no mechanism of action of an intervention needs describing."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is not a review of complex interventions or delivery contexts; no logic model requirement applies."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "This study aims to conduct a meta-analysis focusing on the associations between psychological constructs and sport performance... This study aims to better understand the psychological dynamics of sport performance and develop strategies to optimize performance by mapping the psychological profiles of athletes. The hypotheses of the study are formulated as follows: Hypothesis 1: There is an association between psychological factors... and sport performance. Hypothesis 2: Gender (male/female), athlete type (Elite/Non-elite), and sport type (Team/Individual) moderate the association between psychological factors and sport performance.",
      "reason": "The Introduction explicitly states the review objectives and formal hypotheses specifying the associations and moderators examined."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of associations between psychological factors and performance (correlational meta-analysis), not a review of intervention effects, so PICO-formatted planned comparisons do not apply."
    }
  ],
  "confidence": 90
}

{
