    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "covering articles published from January 2014 to August 1, 2024",
      "reason": "Dissemination year range is specified and text_4 states the review is 'based solely on published studies', but language restrictions and publication status criteria are not explicitly reported."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_7",
      "quote": "No studies were excluded solely due to missing data.",
      "reason": "The review does not distinguish exclusion because outcomes were not measured from exclusion because outcome results were not reported; exclusion reasons given (descriptive statistics only, missing n) do not address this distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "When conducting subgroup analyses based on gender, athlete type, and sport type, appropriate criteria were adopted, and the analyses were included accordingly.",
      "reason": "Synthesis groups (subgroups by gender, athlete type, sport type; psychological factors) are described, but they are not explicitly linked to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "text_6",
      "quote": "covering articles published from January 2014 to August 1, 2024",
      "reason": "Notable restrictions (e.g., the 10-year publication date limit, quantitative designs only) are stated without any rationale."
    }
  ],
  "confidence": 88
}

